    private void Login_btnActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_Login_btnActionPerformed
        String email = Email_Login.getText().trim(); // Ajuste para o nome do campo E-mail
        String senha = new String(Senha_Login.getText()); // ou jTextField2.getText() se for JTextField

        if (email.isEmpty() || senha.isEmpty()) {
            JOptionPane.showMessageDialog(this, "Preencha o e-mail e a senha!");
            return;
        }

        DataSource ds = new DataSource();
        DaoUsuarios dao = new DaoUsuarios(ds);
        Usuarios u = dao.autenticar(email, senha);

        if (u != null) {
            JOptionPane.showMessageDialog(this, "Bem-vindo, " + u.getNome() + "!");
            new Menu().setVisible(true);
            this.dispose();
        } else {
            JOptionPane.showMessageDialog(this, "E-mail ou senha inválidos!", "Erro", JOptionPane.ERROR_MESSAGE);
        }
    }//GEN-LAST:event_Login_btnActionPerformed

    private void Limpar_btnActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_Limpar_btnActionPerformed
        Email_Login.setText("");
        Senha_Login.setText(""); // ou jTextField2.setText("")
        Email_Login.requestFocus();
    }//GEN-LAST:event_Limpar_btnActionPerformed

